5 /**
6  * @title TimeLockSavings
7  * @notice Users can deposit ETH and lock it until a chosen unlock date.
8  *         Withdrawals are only allowed after the unlock time has passed.
9  *         The owner has an emergency withdrawal function to rescue funds.
10  */
11 contract TimeLockSavings {
12     // ---------------------------------------------------------------------
13     // Types
14     // ---------------------------------------------------------------------
15
16     struct Deposit {
17         uint256 amount;       // amount of ETH locked (in wei)
18         uint256 unlockTime;   // unix timestamp when funds become withdrawable
19         bool withdrawn;       // whether this deposit has already been withdrawn
20     }
21
22     // ---------------------------------------------------------------------
23     // State
24     // ---------------------------------------------------------------------
25
26     address public owner;
27
28     /// @notice Each user can have multiple deposits (like different "buckets").
29     mapping(address => Deposit[]) private deposits;
30
31     /// @notice Total amount each user has locked (only counting active deposits).
32     mapping(address => uint256) public lockedBalance;
33
34     /// @notice Total ETH held by the contract (for quick emergency accounting).
35     uint256 public totalLocked;
36
37     // ---------------------------------------------------------------------
38     // Events
39     // ---------------------------------------------------------------------
40
41     event Deposited(
42         address indexed user,
43         uint256 indexed depositId,
44         uint256 amount,
45         uint256 unlockTime
46     );
47     event Withdrawn(
48         address indexed user,
49         uint256 indexed depositId,
50         uint256 amount
51     );
52     event EmergencyWithdrawn(address indexed owner, uint256 amount);
53
54     // ---------------------------------------------------------------------
55     // Modifiers
56     // ---------------------------------------------------------------------
57
58     modifier onlyOwner() {
59         require(msg.sender == owner, "Not owner");
60         _;
61     }
62
63     // ---------------------------------------------------------------------
64     // Constructor
65     // ---------------------------------------------------------------------
66
67     constructor() {
68         owner = msg.sender;
69     }
70
71     // ---------------------------------------------------------------------
72     // External functions
73     // ---------------------------------------------------------------------
74
75     /**
76      * @notice Lock ETH until `unlockTime` (unix timestamp).
77      * @param unlockTime Must be greater than current block.timestamp.
78      * @return depositId The id (index) of the new deposit for the caller.
79      */
80     function deposit(uint256 unlockTime) external payable returns (uint256 depositId) {
81         require(msg.value > 0, "Must send ETH");
82         require(unlockTime > block.timestamp, "Unlock time must be in the future");
83
84         deposits[msg.sender].push(
85             Deposit({
86                 amount: msg.value,
87                 unlockTime: unlockTime,
88                 withdrawn: false
89             })
90         );
91
92         depositId = deposits[msg.sender].length - 1;
93
94         lockedBalance[msg.sender] += msg.value;
95         totalLocked += msg.value;
96
97         emit Deposited(msg.sender, depositId, msg.value, unlockTime);
98     }
99
100     /**
101      * @notice Withdraw a specific deposit after its unlock time.
102      * @param depositId The id of the deposit to withdraw.
103      */
104     function withdraw(uint256 depositId) external {
105         require(depositId < deposits[msg.sender].length, "Invalid deposit id");
106
107         Deposit storage d = deposits[msg.sender][depositId];
108         require(!d.withdrawn, "Already withdrawn");
109         require(block.timestamp >= d.unlockTime, "Still locked");
110
111         uint256 amount = d.amount;
112         d.withdrawn = true;
113
114         lockedBalance[msg.sender] -= amount;
115         totalLocked -= amount;
116
117         (bool ok, ) = payable(msg.sender).call{value: amount}("");
118         require(ok, "ETH transfer failed");
119
120         emit Withdrawn(msg.sender, depositId, amount);
121     }
122
123     /**
124      * @notice Convenience: withdraw all deposits that are currently unlocked.
125      */
126     function withdrawAllUnlocked() external {
127         Deposit[] storage userDeposits = deposits[msg.sender];
128         uint256 totalAmount = 0;
129
130         for (uint256 i = 0; i < userDeposits.length; i++) {
131             Deposit storage d = userDeposits[i];
132             if (!d.withdrawn && block.timestamp >= d.unlockTime) {
133                 totalAmount += d.amount;
134                 d.withdrawn = true;
135                 emit Withdrawn(msg.sender, i, d.amount);
136             }
137         }
138
139         require(totalAmount > 0, "Nothing to withdraw");
140
141         lockedBalance[msg.sender] -= totalAmount;
142         totalLocked -= totalAmount;
143
144         (bool ok, ) = payable(msg.sender).call{value: totalAmount}("");
145         require(ok, "ETH transfer failed");
146     }
147
148     /**
149      * @notice Emergency: owner can withdraw the entire contract balance.
150      * @dev Should only be used if something is seriously wrong.
151      */
152     function emergencyWithdraw() external onlyOwner {
153         uint256 balance = address(this).balance;
154         require(balance > 0, "No balance");
155
156         totalLocked = 0;
157
158         (bool ok, ) = payable(owner).call{value: balance}("");
159         require(ok, "ETH transfer failed");
160
161         emit EmergencyWithdrawn(owner, balance);
162     }
163
164     /**
165      * @notice Transfer contract ownership.
166      */
167     function transferOwnership(address newOwner) external onlyOwner {
168         require(newOwner != address(0), "Zero address");
169         owner = newOwner;
170     }
171
172     // ---------------------------------------------------------------------
173     // View functions
174     // ---------------------------------------------------------------------
175
176     /**
177      * @notice Get a specific deposit for a user.
178      */
179     function getDeposit(address user, uint256 depositId)
180         external
181         view
182         returns (uint256 amount, uint256 unlockTime, bool withdrawn)
183     {
184         require(depositId < deposits[user].length, "Invalid deposit id");
185         Deposit storage d = deposits[user][depositId];
186         return (d.amount, d.unlockTime, d.withdrawn);
187     }
188
189     /**
190      * @notice Get all deposits for a user.
191      */
192     function getUserDeposits(address user)
193         external
194         view
195         returns (Deposit[] memory)
196     {
197         return deposits[user];
198     }
199
200     /**
201      * @notice Number of deposits a user has created.
202      */
203     function getUserDepositCount(address user) external view returns (uint256) {
204         return deposits[user].length;
205     }
206
207     /**
208      * @notice Contract ETH balance.
209      */
210     function contractBalance() external view returns (uint256) {
211         return address(this).balance;
212     }
213
214     // ---------------------------------------------------------------------
215     // Safety
216     // ---------------------------------------------------------------------
217
218     /// @dev Reject plain ETH transfers with no data (must use `deposit`).
219     receive() external payable {
220         revert("Use deposit()");
221     }
222     fallback() external payable {
223         revert("Use deposit()");
224     }
225 }

